namespace generic.theme;




using org.apache.commons.compress.archivers.zip;
using org.apache.commons.compress.archivers.zip;

using ghidra.framework;
using ghidra.util;
using ghidra.util;
using utilities.util;

/**
 * Reads Themes from a file or {@link Reader}
 */
class ThemeReader : AbstractThemeReader {

	/**
	 * The maximum number of allowed image files in a theme zip archive
	 */
	private static readonly int MAX_ZIP_ICON_ENTRIES = 3000;

	private File file;
	private GTheme theme;

	/**
	 * Constructor for reading a theme from a file.
	 * @param file the file to read as a theme
	 * @throws IOException if an I/O error occurs reading the theme file
	 */
	ThemeReader(File file)
    : base(file.getAbsolutePath())
    {
		this.file = file;
	}

	public GTheme readTheme()
    {
		if (file.getName().endsWith(GTheme.FILE_EXTENSION)) {
			return readFileTheme();
		}
		if (file.getName().endsWith(GTheme.ZIP_FILE_EXTENSION)) {
			return readZipTheme();
		}

		throw new IOException("Imported File must end in either " + GTheme.FILE_EXTENSION + " or " +
			GTheme.ZIP_FILE_EXTENSION);
	}

	/**
	 * Assumes the file is a theme file and reads it.
	 */
	private GTheme readFileTheme()
    {
		using (Reader reader = new FileReader(file))
{
			read(reader);
		}
		if (theme == null) {
			throw new IOException("Invalid Theme file: " + file);
		}
		return theme;
	}

	private GTheme readZipTheme()
    {
		using (ZipFile archive = ZipFile.builder().setFile(file).get())
{
			Enumeration<ZipArchiveEntry> entries = archive.getEntries();
			int iconCount = 0;
			while (entries.hasMoreElements()) {
				if (iconCount > MAX_ZIP_ICON_ENTRIES) {
					throw new IOException(
						"Maximum number of extracted icon files (%d) has been exceeded!"
								.formatted(MAX_ZIP_ICON_ENTRIES));
				}
				ZipArchiveEntry entry = entries.nextElement();
				string name = entry.getName();
				if (name.endsWith(".theme")) {
					try (InputStream @is = archive.getInputStream(entry)) {
						processThemeData(name, @is);
					}
				}
				else {
					processIconFile(name, entry, archive);
					iconCount++;
				}
			}
		}
		return theme;
	}

	// for testing
	GTheme readTheme(Reader reader)
    {
		read(reader);
		return theme;
	}

	/* @Override */
	protected void processNoSection(Section section)
    {
		string themeName = section.getValue(ThemeWriter.THEME_NAME_KEY);
		if (themeName == null) {
			throw new IOException("Missing theme name!");
		}
		string lookAndFeelName = section.getValue(ThemeWriter.THEME_LOOK_AND_FEEL_KEY);
		LafType lookAndFeel = LafType.fromName(lookAndFeelName);
		if (lookAndFeel == null) {
			throw new IOException(
				"Invalid or missing lookAndFeel name: \"" + lookAndFeelName + "\"");
		}
		bool isDark = Boolean.valueOf(section.getValue(ThemeWriter.THEME_USE_DARK_DEFAULTS));

		theme = new GTheme(file, themeName, lookAndFeel, isDark);
		section.remove(ThemeWriter.THEME_NAME_KEY);
		section.remove(ThemeWriter.THEME_LOOK_AND_FEEL_KEY);
		section.remove(ThemeWriter.THEME_USE_DARK_DEFAULTS);
		processValues(theme, section);
	}

	/* @Override */
	protected void processDefaultSection(Section section)
    {
		error(section.getLineNumber(), "[Defaults] section not allowed in theme files!");
	}

	/* @Override */
	protected void processDarkDefaultSection(Section section)
    {
		error(section.getLineNumber(), "[Dark Defaults] section not allowed in theme files!");
	}

	/* @Override */
	protected void processCustomSection(Section section)
    {
		error(section.getLineNumber(),
			"Custom sections not allowed in theme files! " + section.getName());
	}

	private void processIconFile(string path, ZipArchiveEntry entry, ZipFile archive)
    {
		int indexOf = path.indexOf("images/");
		if (indexOf < 0) {
			Msg.error(this, "Unknown file: " + path);
			return;
		}

		if (path.contains("..")) {
			// We write the theme images to an 'images' dir under the zip root.  No need for '..'
			Msg.error(this, "Zip paths with '..' not allowed: " + path);
			return;
		}

		string relativePath = path.substring(indexOf, path.length());
		File dir = Application.getUserSettingsDirectory();
		File iconFile = FileUtilities.getSecureFile(dir, relativePath);
		iconFile.getParentFile().mkdirs();
		SecureZipExtractor.extractSecurely(archive, entry, iconFile);
	}

	private void processThemeData(string name, InputStream @is)
    {
		InputStreamReader reader = new InputStreamReader(@is);
		read(reader);
	}

}
